const resp = $input.first().json;
const lead = $('Loop Over Leads').first().json;
const contact = $('Ensure Contact Exists').first().json;
let parsed = {};

try {
  const rawText = resp.candidates[0].content.parts[0].text;
  const cleanJson = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    subject: `${lead.company_name} - Warehouse & Logistics software architecture`,
    body: `Hi there,\n\nI noticed ${lead.company_name}'s operations in ${lead.city}. Queenstown Labs builds bespoke inventory management and distributor automation platforms for regional logistics leaders.\n\nWe recently helped an FMCG distributor eliminate manual order dispatches and reduce coordination latency by 40% using custom web workflows.\n\nWould you be open to a brief 10-minute technical exchange next Tuesday to explore if our software architecture aligns with your roadmap?\n\nBest regards,\nEngineering Team\nQueenstown Labs`,
    personalisation_rationale: 'Targeted logistics workflow optimization',
    quality_score: 85
  };
}

return [{
  json: {
    lead_id: lead.lead_id,
    contact_id: contact.id,
    company_name: lead.company_name,
    subject: parsed.subject,
    body: parsed.body,
    personalisation_notes: parsed.personalisation_rationale,
    quality_score: parsed.quality_score || 85
  }
}];

